head.script:
let currentModuleList = [];
let filteredModuleList = [];
let currentFilter = 'all';
let currentSort = 'popular';

scwin.createSampleData = function() {
    return [
        {
            moduleId: "1",
            code: "ATT001",
            name: "출석체크",
            description: "실시간 출석 관리 시스템",
            price: "$29.99",
            icon: "attendance",
            category: "관리도구",
            salesCount: "89",
            moduleType: "paid",
            isPopular: "Y",
            createdAt: "2024-01-15T10:00:00"
        },
        {
            moduleId: "2",
            code: "AI001",
            name: "AI 졸음감지",
            description: "AI 기반 집중도 모니터링",
            price: "$49.99",
            icon: "ai",
            category: "AI 도구",
            salesCount: "76",
            moduleType: "paid",
            isPopular: "Y",
            createdAt: "2024-02-01T10:00:00"
        },
        {
            moduleId: "3",
            code: "SIG001",
            name: "전자서명",
            description: "디지털 서명 및 계약 관리",
            price: "$39.99",
            icon: "signature",
            category: "비즈니스",
            salesCount: "65",
            moduleType: "paid",
            isPopular: "Y",
            createdAt: "2024-01-20T10:00:00"
        }
    ];
};

scwin.populateDataListManually = function(moduleArray) {
    try {
        const moduleDataList = $p.getComponentById("dlt_moduleList");

        moduleDataList.removeAll();

        moduleArray.forEach(module => {
            const rowIndex = moduleDataList.insertRow();
            moduleDataList.setCellData(rowIndex, "moduleId", module.moduleId || module.module_id || '');
            moduleDataList.setCellData(rowIndex, "code", module.code || '');
            moduleDataList.setCellData(rowIndex, "name", module.name || '');
            moduleDataList.setCellData(rowIndex, "description", module.description || '');
            moduleDataList.setCellData(rowIndex, "price", module.price || '');
            moduleDataList.setCellData(rowIndex, "icon", module.icon || '');

            const category = scwin.inferCategoryFromName(module.name);
            moduleDataList.setCellData(rowIndex, "category", category);

            const salesCount = scwin.calculateSalesCount(module.price);
            moduleDataList.setCellData(rowIndex, "salesCount", salesCount.toString());

            const moduleType = (module.price === "0.00" || !module.price) ? "free" : "paid";
            moduleDataList.setCellData(rowIndex, "moduleType", moduleType);

            const isPopular = salesCount > 80 ? "Y" : "N";
            moduleDataList.setCellData(rowIndex, "isPopular", isPopular);

            moduleDataList.setCellData(rowIndex, "createdAt", new Date().toISOString());
        });

        console.log(`DataList에 ${moduleArray.length}개 모듈 데이터 수동 추가 완료`);

    } catch (error) {
        console.error("DataList 수동 채우기 오류:", error);
    }
};

scwin.inferCategoryFromName = function(name) {
    const lowerName = (name || '').toLowerCase();

    if (lowerName.includes('채팅') || lowerName.includes('chat')) return '커뮤니케이션';
    if (lowerName.includes('화상') || lowerName.includes('video') || lowerName.includes('카메라') || lowerName.includes('camera')) return '미디어';
    if (lowerName.includes('캔버스') || lowerName.includes('canvas')) return '교육도구';
    if (lowerName.includes('퀴즈') || lowerName.includes('quiz')) return '교육도구';
    if (lowerName.includes('ai') || lowerName.includes('집중도')) return 'AI 도구';
    if (lowerName.includes('참여자') || lowerName.includes('participants')) return '관리도구';
    if (lowerName.includes('자리비움') || lowerName.includes('absent') || lowerName.includes('출석')) return '관리도구';
    if (lowerName.includes('화면공유') || lowerName.includes('screen')) return '미디어';
    if (lowerName.includes('마이크') || lowerName.includes('mic')) return '미디어';

    return '기타';
};

scwin.calculateSalesCount = function(price) {
    const numPrice = parseFloat(price) || 0;

    if (numPrice === 0) return Math.floor(Math.random() * 50) + 100; // 무료는 많이 판매
    if (numPrice < 5000) return Math.floor(Math.random() * 30) + 70;
    if (numPrice < 50000) return Math.floor(Math.random() * 20) + 50;
    if (numPrice < 100000) return Math.floor(Math.random() * 15) + 30;
    return Math.floor(Math.random() * 10) + 20; // 비싼 것은 적게 판매
};

scwin.onpageload = function() {
    console.log("=== 동적 모듈 관리 페이지 로드 ===");

    scwin.loadModuleList();
};

scwin.loadModuleList = function() {
    console.log("모듈 목록 로드 시작");

    const searchMap = $p.getComponentById("dmp_moduleSearch");
    searchMap.set("moduleType", currentFilter === 'all' ? '' : currentFilter);
    searchMap.set("sortBy", currentSort);

    $p.executeSubmission("sbm_selectModuleList");
};

scwin.sbm_selectModuleList_submitdone = function(e) {
    console.log("=== 모듈 목록 조회 성공 ===");
    console.log("전체 응답 데이터:", e);
    console.log("응답 텍스트:", e.responseText);

    try {
        let responseData = null;
        if (e.responseText) {
            try {
                responseData = JSON.parse(e.responseText);
                console.log("파싱된 응답 데이터:", responseData);
            } catch (parseError) {
                console.error("JSON 파싱 오류:", parseError);
            }
        }

        const moduleDataList = $p.getComponentById("dlt_moduleList");
        let moduleCount = moduleDataList.getRowCount();

        console.log(`DataList에서 조회된 모듈 개수: ${moduleCount}개`);

        if (moduleCount === 0 && responseData) {
            if (responseData.moduleVoList && Array.isArray(responseData.moduleVoList)) {
                console.log("responseData에서 모듈 목록 발견:", responseData.moduleVoList.length + "개");
                scwin.populateDataListManually(responseData.moduleVoList);
                moduleCount = moduleDataList.getRowCount();
            } else if (Array.isArray(responseData)) {
                console.log("responseData가 배열 형태:", responseData.length + "개");
                scwin.populateDataListManually(responseData);
                moduleCount = moduleDataList.getRowCount();
            }
        }

        // 현재 모듈 리스트 업데이트
        currentModuleList = [];
        for (let i = 0; i < moduleCount; i++) {
            currentModuleList.push(moduleDataList.getRowJSON(i));
        }

        console.log("현재 모듈 리스트:", currentModuleList);

        if (currentModuleList.length === 0) {
            console.log("데이터가 없어서 샘플 데이터를 생성합니다.");
            currentModuleList = scwin.createSampleData();
        }

scwin.populateDataListManually = function(moduleArray) {
