scwin.sbm_selectModuleList_submiterror = function(e) {
    console.error("=== 모듈 목록 조회 실패 ===");
    console.error("오류:", e);

    console.log("API 오류로 인한 샘플 데이터 생성");
    currentModuleList = scwin.createSampleData();
    scwin.calculateAndUpdateStats();
    scwin.renderModuleList();

    setTimeout(() => {
        alert("모듈 목록 조회에 실패했습니다. 샘플 데이터를 표시합니다.");
    }, 1000);
};

scwin.calculateAndUpdateStats = function() {
    const stats = {
        totalModules: currentModuleList.length,
        freeModules: currentModuleList.filter(m => !m.price || m.price === '0.00' || m.price === '0' || m.moduleType === 'free').length,
        paidModules: currentModuleList.filter(m => m.price && m.price !== '0.00' && m.price !== '0' && m.moduleType !== 'free').length,
        monthlyRevenue: scwin.calculateMonthlyRevenue()
    };

    console.log("계산된 통계:", stats);

    // UI 업데이트
    scwin.updateStatsUI(stats);
};

scwin.calculateMonthlyRevenue = function() {
    let revenue = 0;
    currentModuleList.forEach(module => {
        if (module.price && module.salesCount) {
            const price = parseFloat(module.price) || 0;
            const sales = parseInt(module.salesCount) || 0;
            revenue += price * sales * 0.01; // 월간 매출의 1%로 가정 (한국 원화)
        }
    });
    return Math.round(revenue);
};

scwin.updateStatsUI = function(stats) {
    try {
        setTimeout(() => {
            const statNumbers = document.querySelectorAll('.stat-number');
            if (statNumbers.length >= 4) {
                statNumbers[0].textContent = stats.totalModules;
                statNumbers[1].textContent = `₩${stats.monthlyRevenue.toLocaleString()}`;
                statNumbers[2].textContent = stats.freeModules;
                statNumbers[3].textContent = stats.paidModules;
                console.log("통계 UI 업데이트 완료");
            }
        }, 100);
    } catch (error) {
        console.error("통계 UI 업데이트 오류:", error);
    }
};

// 모듈 목록 렌더링
scwin.renderModuleList = function() {
    console.log("모듈 목록 렌더링 시작");

    try {
        // 필터링 적용
        filteredModuleList = scwin.applyFilter(currentModuleList);

        // 정렬 적용
        filteredModuleList = scwin.applySorting(filteredModuleList);

        // 상위 5개만 표시 (인기 모듈 TOP 5)
        const topModules = filteredModuleList.slice(0, 5);

        // UI 업데이트
        scwin.updateModuleListUI(topModules);

        console.log(`${topModules.length}개 모듈 렌더링 완료`);

    } catch (error) {
        console.error("모듈 목록 렌더링 오류:", error);
    }
};

// 필터 적용
scwin.applyFilter = function(moduleList) {
    if (currentFilter === 'all') {
        return [...moduleList];
    }

    return moduleList.filter(module => {
        switch (currentFilter) {
            case 'free':
                return !module.price || module.price === '0.00' || module.price === '0' || module.moduleType === 'free';
            case 'paid':
                return module.price && module.price !== '0.00' && module.price !== '0' && module.moduleType === 'paid';
            case 'new':
                // 최근 30일 내 생성된 모듈
                if (module.createdAt) {
                    const created = new Date(module.createdAt);
                    const thirtyDaysAgo = new Date();
                    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
                    return created > thirtyDaysAgo;
                }
                return false;
            case 'popular':
                return module.isPopular === 'Y' || (module.salesCount && parseInt(module.salesCount) > 80);
            default:
                return true;
        }
    });
};

// 정렬 적용
scwin.applySorting = function(moduleList) {
    return [...moduleList].sort((a, b) => {
        switch (currentSort) {
            case 'popular':
                return (parseInt(b.salesCount) || 0) - (parseInt(a.salesCount) || 0);
            case 'price_low':
                return (parseFloat(a.price?.replace(/[^0-9.]/g, '')) || 0) - (parseFloat(b.price?.replace(/[^0-9.]/g, '')) || 0);
            case 'price_high':
                return (parseFloat(b.price?.replace(/[^0-9.]/g, '')) || 0) - (parseFloat(a.price?.replace(/[^0-9.]/g, '')) || 0);
            case 'name':
                return (a.name || '').localeCompare(b.name || '');
            case 'newest':
                return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);
            default:
                return 0;
        }
    });
};

// 모듈 목록 UI 업데이트
scwin.updateModuleListUI = function(modules) {
    try {
        const moduleListContainer = document.querySelector('.module-list');
        if (!moduleListContainer) {
            console.error("모듈 리스트 컨테이너를 찾을 수 없음");
            return;
        }

        // 기존 모듈 아이템 제거
        moduleListContainer.innerHTML = '';

        if (modules.length === 0) {
            moduleListContainer.innerHTML = '<div class="no-modules">표시할 모듈이 없습니다.</div>';
            return;
        }

        // 모듈 아이템 생성
        modules.forEach((module, index) => {
            const moduleItem = scwin.createModuleItemElement(module, index + 1);
            moduleListContainer.appendChild(moduleItem);
        });

    } catch (error) {
        console.error("모듈 목록 UI 업데이트 오류:", error);
    }
};

// 모듈 아이템 요소 생성
scwin.createModuleItemElement = function(module, rank) {
    const moduleItem = document.createElement('div');
    moduleItem.className = 'module-item';
    moduleItem.onclick = () => scwin.showModuleDetail(module);

    // 아이콘 클래스 결정
    const iconClass = scwin.getModuleIconClass(module.name, module.category);
    const iconText = scwin.getModuleIconText(module.name);

    // 가격 표시 처리
    const priceDisplay = scwin.formatPrice(module.price);
    const categoryDisplay = module.category || '기타';
    const salesDisplay = module.salesCount ? `${module.salesCount}구매` : '신규';

    moduleItem.innerHTML = `
        <div class="module-icon ${iconClass}">
            ${iconText}
        </div>
        <div class="module-info">
            <div class="module-name">${module.name || 'Unknown Module'}</div>
            <div class="module-details">${priceDisplay} | ${categoryDisplay}</div>
        </div>
        <div class="module-sales">${salesDisplay}</div>
        <div class="module-rank">#${rank}</div>
    `;

    return moduleItem;
};

// 모듈 아이콘 클래스 결정
scwin.getModuleIconClass = function(name, category) {
    const lowerName = (name || '').toLowerCase();
    const lowerCategory = (category || '').toLowerCase();

    if (lowerName.includes('출석') || lowerName.includes('attendance')) return 'icon-attendance';
    if (lowerName.includes('ai') || lowerName.includes('졸음')) return 'icon-ai';
    if (lowerName.includes('서명') || lowerName.includes('sign')) return 'icon-signature';
    if (lowerName.includes('녹화') || lowerName.includes('record')) return 'icon-record';
    if (lowerName.includes('퀴즈') || lowerName.includes('quiz')) return 'icon-quiz';
    if (lowerName.includes('채팅') || lowerName.includes('chat')) return 'icon-chat';
    if (lowerName.includes('화면') || lowerName.includes('screen')) return 'icon-screen';
    if (lowerCategory.includes('교육')) return 'icon-education';
    if (lowerCategory.includes('비즈니스')) return 'icon-business';
    if (lowerCategory.includes('미디어')) return 'icon-media';

    return 'icon-default';
};

// 모듈 아이콘 텍스트 결정
scwin.getModuleIconText = function(name) {
    const lowerName = (name || '').toLowerCase();

    if (lowerName.includes('출석')) return '출석';
    if (lowerName.includes('ai')) return 'AI';
    if (lowerName.includes('서명')) return '서명';
    if (lowerName.includes('녹화')) return '녹화';
    if (lowerName.includes('퀴즈')) return '퀴즈';
    if (lowerName.includes('채팅')) return '채팅';
    if (lowerName.includes('화면')) return '화면';

    return (name || 'M').charAt(0).toUpperCase();
};

// 가격 포맷팅
scwin.formatPrice = function(price) {
    if (!price || price === '0.00' || price === '0') {
        return '무료';
    }

    const numPrice = parseFloat(price);
    if (!isNaN(numPrice)) {
        if (numPrice >= 1000) {
            return `₩${numPrice.toLocaleString()}`;
        } else {
            return `₩${numPrice}`;
        }
    }

    return price;
};

// 필터 버튼 클릭 이벤트
scwin.filterNew = function() {
    scwin.setActiveFilter('new');
    currentFilter = 'new';
    currentSort = 'newest';
    scwin.loadModuleList();
};

scwin.filterPopular = function() {
    scwin.setActiveFilter('popular');
    currentFilter = 'popular';
    currentSort = 'popular';
    scwin.loadModuleList();
};

scwin.filterPrice = function() {
    scwin.setActiveFilter('price');
    currentFilter = 'all';
    currentSort = 'price_high';
    scwin.loadModuleList();
};

scwin.filterFree = function() {
    scwin.setActiveFilter('free');
    currentFilter = 'free';
    currentSort = 'popular';
    scwin.loadModuleList();
};

scwin.filterPaid = function() {
    scwin.setActiveFilter('paid');
    currentFilter = 'paid';
    currentSort = 'popular';
    scwin.loadModuleList();
};

scwin.setActiveFilter = function(filterType) {
    try {
        document.querySelectorAll('.filter-btn').forEach(btn => {
            btn.classList.remove('active');
        });

        const activeBtn = document.querySelector(`[data-filter="${filterType}"]`);
        if (activeBtn) {
            activeBtn.classList.add('active');
        }
    } catch (error) {
        console.error("필터 버튼 활성화 오류:", error);
    }
};

scwin.showModuleDetail = function(module) {
    const detailInfo = `모듈 상세 정보:

이름: ${module.name || 'N/A'}
설명: ${module.description || 'N/A'}
가격: ${scwin.formatPrice(module.price)}
카테고리: ${module.category || 'N/A'}
판매수: ${module.salesCount || 0}구매
모듈ID: ${module.moduleId || 'N/A'}
코드: ${module.code || 'N/A'}`;

    alert(detailInfo);
};

scwin.showDetail = function() {
    alert(`전체 모듈 목록

총 ${currentModuleList.length}개의 모듈이 있습니다.

- 무료 모듈: ${currentModuleList.filter(m => !m.price || m.price === '0' || m.price.toLowerCase() === 'free').length}개
- 유료 모듈: ${currentModuleList.filter(m => m.price && m.price !== '0' && m.price.toLowerCase() !== 'free').length}개
- 인기 모듈: ${currentModuleList.filter(m => m.isPopular === 'Y' || (m.salesCount && parseInt(m.salesCount) > 50)).length}개`);
};

// 모듈 새로고침
scwin.refreshModules = function() {
    console.log("모듈 목록 새로고침");
    scwin.loadModuleList();
};

// 에러 메시지 표시
scwin.showErrorMessage = function(message) {
    try {
        // 통계 카드를 기본값으로 리셋
        setTimeout(() => {
            const statNumbers = document.querySelectorAll('.stat-number');
            if (statNumbers.length >= 4) {
                statNumbers[0].textContent = '0';
                statNumbers[1].textContent = '₩0';
                statNumbers[2].textContent = '0';
                statNumbers[3].textContent = '0';
            }
        }, 100);

        // 모듈 리스트에 에러 메시지 표시
        const moduleListContainer = document.querySelector('.module-list');
        if (moduleListContainer) {
            moduleListContainer.innerHTML = `
                <div class="error-message">
                    <div class="error-icon">⚠️</div>
                    <div class="error-text">${message}</div>
                    <button class="retry-btn" onclick="scwin.refreshModules()">다시 시도</button>
                </div>
            `;
        }

        console.error("에러 메시지 표시:", message);
    } catch (error) {
        console.error("에러 메시지 표시 중 오류:", error);
    }
};

